raw:
{
  "spells": [
    {
      "id": "spell_water_04",
      "theory": "引水术把魔力铺在沟渠内壁的湿泥上，使水沿已有沟槽滑行。水流必须由现有水源补充，术式只降低水与渠壁的摩擦并把水推向前方。若沟渠断裂或高于水源，水便停在断口，不会漫出沟沿，也不会凭空涌出。河谷农户常用它把溪水引入菜畦，但每一段沟渠都得事先挖通。",
      "casting": "蹲在沟边，双掌浸入水中，沿水面向下游缓缓划出三道平行短线，每划一道便向前推送一次魔力。",
      "failure": "魔力推送不均时，水会在沟中打旋或倒流一小段，浸湿两侧泥土。若沟渠本身有缺口，水会从缺口渗出，把田埂泡软，需要人工堵回。",
      "counters": [
        "在上游截断水源，沟中存水用尽后术式自然停止。",
        "在沟渠中段挖开缺口，水会改道流出，不再受术式推动。"
      ],
      "socialConsequences": "河谷乡约承认引水术为公开农事，邻里间按沟渠先后顺序用水。上游农户若在旱季截流，下游会要求乡约见证重新分水。养鱼户担心渠水被引走影响鱼塘，但通常接受在非产卵季施术。商队经过时若借沟饮马，须先问明主人，避免踩塌田埂。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时水流忽快忽慢，需要反复调整双掌推送的力度。",
        "熟练后能维持稳定流速，减少沟壁被冲蚀的泥浆。",
        "精准控制下可让水在细窄沟中直线前行，不漫上田垄。",
        "高熟练度使水量分配更均匀，仍不能超过沟渠容量。"
      ]
    },
    {
      "id": "spell_water_05",
      "theory": "止漏膜把魔力凝在容器漏口的边缘，形成一层贴合缝隙的透明水膜。水膜依靠容器内外的压力差维持，压力过大时会被顶破。它只封住已存在的孔洞，不能加固开裂的桶壁，也不能把两块碎片粘回原状。中陆城市的酒商和水贩常用它应急，但不会拿它替代箍桶匠的修理。",
      "casting": "用食指蘸水，沿漏口边缘画一圈闭合细线，同时把魔力压入缝隙，直到水膜泛出微光。",
      "failure": "魔力分布不均时水膜会鼓起气泡，随后从最薄处破裂，漏口重新喷水。若漏口边缘有油污，水膜无法附着，术式会直接滑落，浪费一次施术。",
      "counters": [
        "用硬物刮破水膜边缘，压力差会使整层膜迅速崩解。",
        "向容器内注入超过水膜承受压力的水量，膜会被顶破。"
      ],
      "socialConsequences": "城市公会视止漏膜为公开的应急手艺，但要求施术者不得用它掩盖货损。港口装货时若用止漏膜封桶，须在运单上注明，否则收货方发现后可按货损追究。箍桶匠不反对小漏应急，但担心有人长期依赖水膜而拖延正式修补。酒商在集市上展示止漏膜时，须让买主看清漏口位置。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时水膜容易歪斜，只封住漏口的一半。",
        "熟练后能贴合不规则缝隙，减少施术时的水花。",
        "精准控制下可判断压力上限，提前提醒货主卸货。",
        "高熟练度使水膜维持更久，仍不能超过容器承压极限。"
      ]
    },
    {
      "id": "spell_water_06",
      "theory": "清渠术把魔力送入沟底淤泥，使泥粒之间的水膜松开，淤泥变得松散易铲。它只改变泥的黏结状态，不会让泥自己浮起或流走。沟中必须有人用锹把松泥运到岸上，否则泥会重新沉积。琥珀海岸的船坞在退潮后用它清理排水沟，但淤泥仍须堆到指定地点，不能推进别人的泊位。",
      "casting": "单膝跪在沟边，把掌心贴在淤泥表面，沿沟底画一条缓慢的波浪线，同时向泥中沉入魔力。",
      "failure": "魔力沉入过深时，淤泥会变成稀泥浆，人踩上去容易陷脚。若沟底有硬石，术式会在石面滑开，只松动半边泥层，留下难铲的硬块。",
      "counters": [
        "向沟中灌入大量清水，松泥会被冲散并重新沉积。",
        "在沟底铺一层碎石，魔力无法均匀传入淤泥，术式效果减半。"
      ],
      "socialConsequences": "港口规定清渠术可用于船坞和公共排水沟，但松出的淤泥必须运到指定堆场。船主若把泥推入邻船泊位，会被港务追究货损和碍航。清淤工愿意用此术省力，却要求船主另行支付运泥人工。岸上住户担心淤泥堆在门前，常要求先商定堆放位置。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时只松动表层薄泥，深处仍硬结成块。",
        "熟练后能均匀松泥，减少稀泥浆和陷脚风险。",
        "精准控制下可避开沟底硬石，只处理淤泥层。",
        "高熟练度使松泥深度一致，仍须人工运走淤泥。"
      ]
    }
  ]
}
